CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,checksum TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,root TEXT NOT NULL,current_generation_id TEXT,epoch INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS source_snapshots(id TEXT PRIMARY KEY,manifest_digest TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS index_generations(id TEXT PRIMARY KEY,snapshot_id TEXT NOT NULL REFERENCES source_snapshots(id),path TEXT NOT NULL,coverage TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('READY','RETIRED')));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,payload_digest TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','ABORTED')),result TEXT,error TEXT);
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,payload TEXT NOT NULL,occurred_at TEXT NOT NULL);
